  "Code that is tested before you get it": "Код, проверенный до того, как вы его получите",
  "The model writes the program and its tests, the phone runs them, and any error goes straight back to the model to fix — until the tests pass. Offline, in a locked sandbox.": "Модель пишет программу и тесты к ней, телефон их запускает, а любая ошибка сразу уходит модели на исправление — пока тесты не пройдут. Офлайн, в закрытой песочнице.",
  "What should it do? e.g. “A function that splits a restaurant bill between friends, with the tip”": "Что оно должно делать? напр. «Функция, которая делит счёт в ресторане между друзьями, с чаевыми»",
