  "= instant on-device scaffolding.": "= мгновенная заготовка на устройстве.",
  "= the model rethinks and rephrases your prompt.": "= модель переосмысливает и переформулирует ваш промпт.",
  "Tailored for": "Адаптировано для",
  "Write a rough prompt, then hit": "Напишите черновой промпт и нажмите",
  "to see the model rethink it — or Structure for an instant offline version.": "— модель его переосмыслит. Или «Структура» для мгновенной офлайн-версии.",
  "Your new prompt": "Ваш новый промпт",
  "Paste a long, wordy prompt — AI Compress will think and shrink it.": "Вставьте длинный многословный промпт — «Сжать ИИ» подумает и сократит его.",
  "Chat history": "История чата",
  "Paste the earlier messages — anything already established gets dropped.": "Вставьте прошлые сообщения — всё, что уже известно, будет убрано.",
  "Compress to": "Сжать до",
  "% of original": "% от исходного",
  "10% · brutal": "10% · жёстко",
