  "per company system, once": "за систему компании, один раз",
  "Pro is bought in the Google Play version of Attune — one tap, paid by card or from your Vodafone / Orange / Etisalat balance, and it switches on by itself.": "Pro покупается в версии Attune из Google Play — одним касанием, картой или со счёта Vodafone / Orange / Etisalat, и включается сам.",
  "Cancel any time in Google Play → Subscriptions. The plan renews by itself; nothing to send, nobody to message.": "Отменить можно в любой момент: Google Play → Подписки. Тариф продлевается сам — ничего не нужно отправлять и никому писать.",
  "I have an activation code (company deals)": "У меня есть код активации (для компаний)",
