  "Subtitles (.srt)": "Субтитры (.srt)",
  "Subtitles (.vtt)": "Субтитры (.vtt)",
  "Merge into one PDF": "Объединить в один PDF",
  "Split into pages": "Разделить на страницы",
  "PDFs": "Файлы PDF",
  "PowerPoint": "PowerPoint",
  "LibreOffice text": "Текст LibreOffice",
  "LibreOffice sheet": "Таблица LibreOffice",
  "E-book": "Электронная книга",
  "Rich Text": "Форматированный текст",
  "JSON data": "Данные JSON",
  "Subtitles": "Субтитры",
  "{n} PDFs": "Файлов PDF: {n}",
  "{n} pages": "Страниц: {n}",
  "Converting photo {n} of {t}…": "Конвертируем фото {n} из {t}…",
  "This phone can't write that photo type — try JPG or PNG.": "Этот телефон не умеет сохранять фото в таком формате — попробуйте JPG или PNG.",
  "This photo can't be opened here (HEIC photos: convert them to PDF instead).": "Это фото здесь не открыть (фото HEIC лучше конвертировать в PDF).",
  "No text was found in that file.": "В этом файле не найден текст.",
  "This PDF has no clear table, so each line became a row — check the columns.": "В этом PDF нет чёткой таблицы, поэтому каждая строка стала отдельной строкой таблицы — проверьте столбцы.",
