  "It knows how things actually work here — fair prices, common overcharges, what's rude. It will tell you when something needs live data it can't have offline.": "Знает, как здесь всё устроено на самом деле — честные цены, частые накрутки, что считается невежливым. Скажет, если для ответа нужны свежие данные, недоступные офлайн.",
