  "Backup & restore": "Резервная копия и восстановление",
  "Everything in Attune lives only on this phone. A backup is one file, locked with your password, that you can keep anywhere.": "Всё в Attune хранится только на этом телефоне. Резервная копия — это один файл, защищённый вашим паролем, который можно хранить где угодно.",
  "Back up": "Создать копию",
