  "If you forget this password the backup cannot be opened — by anyone. Write it down somewhere safe.": "Если вы забудете этот пароль, резервную копию не сможет открыть никто. Запишите его в надёжном месте.",
  "Lock and save backup": "Защитить и сохранить копию",
