  "Replace everything on this phone": "Заменить всё на этом телефоне",
  "This phone becomes exactly like the backup.": "Этот телефон станет точно таким же, как в копии.",
  "Merge": "Объединить",
  "Keep everything on this phone and add the backup's chats, memory, reminders and cycle days. The Money ledger is only taken from the backup if this phone has none.": "Оставить всё на этом телефоне и добавить чаты, память, напоминания и дни цикла из копии. Денежная книга берётся из копии, только если на этом телефоне её нет.",
  "This phone's {c} chats and {l} ledger entries will be replaced by the backup's. You can undo this once, right after.": "Чаты ({c}) и записи денежной книги ({l}) на этом телефоне будут заменены данными из копии. Это можно отменить один раз, сразу после.",
  "The backup's items will be added to this phone. You can undo this once, right after.": "Данные из копии будут добавлены на этот телефон. Это можно отменить один раз, сразу после.",
