  "What are the key points?": "Каковы ключевые моменты?",
  "Checklist: what every answer must satisfy (one per line, optional)": "Чек-лист: чему должен отвечать каждый ответ (по одному на строку, необязательно)",
  "Facts the AI should know (prices, rules, terms — optional)": "Факты, которые должен знать ИИ (цены, правила, условия — необязательно)",
  "Separate topics with an empty line. Only the paragraphs that fit the question are used, so this can be long.": "Разделяйте темы пустой строкой. Используются только абзацы, подходящие к вопросу, поэтому текст может быть длинным.",
  "Facts": "Факты",
  "It also runs this small program on your phone (offline, in a locked box — no internet, no files, no access to the app)": "Он также запускает эту небольшую программу на вашем телефоне (офлайн, в изолированной среде — без интернета, файлов и доступа к приложению)",
  "Edit or improve my CV": "Изменить или улучшить моё резюме",
  "Say what to add or change («add my job at Dar Al Fouad Hospital as a nurse, 2019–2022», «change my phone to …»), or leave it empty and just make it more professional. You see the result before it is kept.": "Скажите, что добавить или изменить («добавь мою работу медсестрой в больнице Dar Al Fouad, 2019–2022», «измени мой телефон на …»), или оставьте пустым — тогда резюме просто станет профессиональнее. Вы увидите результат до сохранения.",
  "What should be added or changed? (optional)": "Что добавить или изменить? (необязательно)",
  "Apply my change": "Применить моё изменение",
  "Change + make it professional": "Изменить и сделать профессиональнее",
  "New version": "Новая версия",
  "Use this version": "Использовать эту версию",
  "Done — you can undo it": "Готово — это можно отменить",
  "Undo the last change": "Отменить последнее изменение",
  "Stuck — starting again from scratch with a different approach": "Не получилось — начинаю с нуля другим подходом",
  "Wrote it, with {n} tests.": "Написано, тестов: {n}.",
