  "✓ Ran without errors.": "✓ Выполнено без ошибок.",
  "The fix did not match the code.": "Исправление не подошло к коду.",
  "The model answered without code.": "Модель ответила без кода.",
  "The fix deleted the tests — refused.": "Исправление удаляло тесты — отклонено.",
  "The model answered without any code — try asking again in other words.": "Модель ответила совсем без кода — попробуйте спросить другими словами.",
  "A picture — Studio draws it on this phone": "Картинка — Studio рисует её на этом телефоне",
  "Another version": "Другая версия",
  "Could not open that picture": "Не удалось открыть эту картинку",
  "Could not save": "Не удалось сохранить",
  "Current photo quality in 4 steps: people, places, products and text in pictures. Also edits a photo you give it (“make it night”, “remove the car”).": "Современное качество фото в 4 шага: люди, места, товары и текст на картинках. Также редактирует переданное фото («сделай ночь», «убери машину»).",
  "Describe the picture, in Arabic or English — e.g. “a felucca on the Nile at sunset”": "Опишите картинку на арабском или английском — напр. «фелюга на Ниле на закате»",
  "Developing the picture…": "Проявляю картинку…",
  "Download it on Wi-Fi. After that, pictures are made with no internet at all.": "Скачайте по Wi-Fi. После этого картинки создаются совсем без интернета.",
  "Draw it": "Нарисовать",
  "Draw it in Studio": "Нарисовать в Studio",
  "A place — Maps finds it": "Место — найдут «Карты»",
  "Show on the map": "Показать на карте",
  "Draw on the graphics chip (faster; switches itself off if the driver fails)": "Рисовать на графическом чипе (быстрее; сам отключится, если драйвер откажет)",
  "Drawing on the GPU failed, so Attune switched Studio to the CPU. ": "Рисование на GPU не удалось, поэтому Attune переключил Studio на CPU. ",
  "Drawing — step {n} of {t}": "Рисую — шаг {n} из {t}",
  "Each picture is made by a separate engine process: when it finishes, all its memory goes back to the phone. Nothing is uploaded.": "Каждая картинка создаётся отдельным процессом движка: когда он завершается, вся его память возвращается телефону. Ничего не загружается.",
  "Edit a photo": "Редактировать фото",
