  "The best pictures this phone can make: the 8-bit build of FLUX.2 klein — finer detail, cleaner faces, hands and text. Also edits your photos by instruction.": "Лучшие картинки, какие может делать этот телефон: 8-битная сборка FLUX.2 klein — тоньше детали, чище лица, руки и текст. Также редактирует ваши фото по инструкции.",
  "That file is too large (15 MB at most)": "Этот файл слишком большой (не более 15 МБ)",
