  "Wrong? Teach the right answer": "Неверно? Научите правильному ответу",
  "What should it have said? Chat will answer this way next time you ask something like it.": "Что нужно было ответить? В следующий раз Чат ответит так на похожий вопрос.",
  "The right answer": "Правильный ответ",
  "Why (optional) — e.g. “the marble falls out when the glass is turned over”": "Почему (необязательно) — напр. «шарик выпадает, когда стакан переворачивают»",
  "Learned — Chat will use this on similar questions": "Усвоено — Чат будет использовать это на похожих вопросах",
