  "Still working — nothing is stuck. On the CPU a picture takes about 3–10 minutes (edits are slower than new pictures). Keep Attune open; Stop cancels it.": "Всё ещё работаю — ничего не зависло. На CPU картинка занимает около 3–10 минут (правки медленнее новых картинок). Держите Attune открытым; «Стоп» отменяет.",
